equation_logic_text:
//outputs
var calc_output = [];

//user inputs
var fro = parseFloat(fro);
var to = parseFloat(to);
var dose = parseFloat(dose);

//fro should correspond to a value in this dict
var assign = {"Morphine (oral)": 0, "Morphine (parenteral)": 1, "Buprenorphine (SL)": 2, "Buprenorphine (parenteral)": 3, "Codeine (oral)": 4, "Codeine (parenteral)": 5, "Fentanyl (parenteral)": 6, "Hydrocodone (oral)": 7, "Hydromorphone (parenteral)": 8, "Hydromorphone (oral)": 9, "Meperidine (oral)": 10, "Meperidine (parenteral)": 11, "Oxycodone (oral)": 12, "Oxycodone (parenteral)": 13, "Oxymorphone (parenteral)": 14, "Oxymorphone (oral)": 15, "Tapentadol (oral)": 16, "Tramadol (oral)": 17, "Tramadol (parenteral)": 18};

//find the from and to drugs
var from_drug, to_drug;
for(var key in assign){
	var value = assign[key]; //will be from 0-17
	if (fro == value){
		from_drug = key;
	}
	if(to == value){
		to_drug = key;
	}
}

//dict = {key1: "value1", key2: "value2"}, because Yi is mean and won't send JSON labels to me :(
var dict = {"Morphine (oral)": 25, "Morphine (parenteral)": 10, "Buprenorphine (SL)": 0.4, "Buprenorphine (parenteral)": 0.3, "Codeine (oral)": 200, "Codeine (parenteral)": 100, "Fentanyl (parenteral)": 0.15, "Hydrocodone (oral)": 25, "Hydromorphone (parenteral)": 2, "Hydromorphone (oral)": 5, "Meperidine (oral)": 300, "Meperidine (parenteral)": 100, "Oxycodone (oral)": 20, "Oxycodone (parenteral)": 10, "Oxymorphone (parenteral)": 1, "Oxymorphone (oral)": 10, "Tapentadol (oral)": 100, "Tramadol (oral)": 120, "Tramadol (parenteral)": 100};

var from_multi, to_multi;
for(var key in dict){
	if (key == from_drug){
		from_multi = dict[key];
	}
	if (key == to_drug){
		to_multi = dict[key];
	}
}

//calculation
var u = (dose / from_multi)*to_multi; 

// drugs that require three decimal points in the output
var three_decimal_drugs = ["Buprenorphine (SL)", "Buprenorphine (parenteral)", "Fentanyl (parenteral)"];

//formatting output based on drug type
var formatted_u;
if (three_decimal_drugs.includes(to_drug)) {
    formatted_u = u.toFixed(3); // show 3 decimal points
} else {
    formatted_u = u.toFixed(0); // show 0 decimal points
}

var msg = "Approximate " + to_drug + " equivalence to: " + dose + "mg of " + from_drug;

//result user sees
calc_output.push({
    name: 'mini',
    value: formatted_u,
    value_text: 'mg',
    message: msg
});
calc_output.push({
    name: '3947_Opiate Conversion_result',
    value: formatted_u,
    value_text: 'mg',
    message: msg
});
